import csv, json
from pathlib import Path
import numpy as np

B=Path(__file__).resolve().parent
q=list(csv.DictReader((B/'queue.csv').open()))
g=json.loads((B/'gaia-geometry.json').read_text())
n=json.loads((B/'neighbor-inspection.json').read_text())
assess={
'357019754':dict(verdict='confirmed',limitations='Representative three QLP sectors; three s12 center covariances are singular and excluded, while another s12 center remains usable. The shallow secondary is visible but its own ephemeris was not fitted.',next='Obtain a separate reduction with a measured secondary depth and more precise primary/secondary geometry.',reason='Deep flat-bottomed same-kind dips repeat in sectors 12, 65 and 93. A shallower dip near phase 0.5 supports the Gaia-like orbital period. Cached s38 TESScut deficit is compact on target with no flux-capable Gaia neighbor in its search.',source='Fable 5/made/sb1-scale/c10-flags.md; diffimg/357019754/diff_s38.json'),
'187202091':dict(verdict='confirmed',limitations='Sectors 73/86 have curved SAP baselines; their free trapezoid centers are rejected. Adopted local-minimum time widths are heuristic, so period error is conditional. Gaia conjunction phase has weak discrimination after long extrapolation. Six cached pixel events peak on target, but the 17.1-arcsec Gaia alternative is only disfavored by uncalibrated centroid geometry; subpixel companions remain unresolved.',next='Measure high-cadence eclipse times and a second reduction with a flexible local baseline; resolve any close unseen companion.',reason='Five local SAP minima recur over 180 photometric cycles; s19 and both s59 raw dips are directly clear, and the historical all-sector stack passes empirical off-phase tests. The s19/59/73/86 TESScut stacks put six of six deficit peaks on the target pixel and disfavor resolved capable neighbors. Measured and Gaia periods differ by about 2.47 Gaia standard errors, within the broad source-specific extrapolation allowance but weakening orbital identification.',source='Fable 5/made/sb1-scale/c10-marg-persec.md; persec187-out.txt; diffimg/c10-187202091-diffimg.md'),
'54054420':dict(verdict='probable',limitations='A G17.60 source only 7.9 arcsec from target is flux-capable and 6.4 arcsec from cached deficit centroid; s24 PSF residual is 0.65 without calibrated centroid covariance. Nearly equal alternating dips leave the photometric half-period alias unresolved by photometry alone. TIC radius 5.07 solar radii gives longer central eclipse than observed; grazing geometry or stellar radius errors could reconcile it.',next='Obtain higher-resolution time-series photometry or spatially resolved difference imaging to identify which 7.9-arcsec source dims.',reason='Repeated short dips in s18, s52 and s85 occur at a 2.22227-d photometric interval. Same-kind even-cycle events give 4.44455 d, matching Gaia; the odd dips have similar depth. The cached s24 TESScut deficit peaks on the target pixel, but it does not resolve the closest capable neighbor.',source='Fable 5/made/sb1-scale/c10-flags.md; diffimg/54054420/diff_s24.json'),
'462088261':dict(verdict='plausible',limitations='Large correlated orbital modulation and curved local baselines make the shallow narrow component hard to isolate as an eclipse. Target is an exact VSX RS variable. G15.56 and G18.13 sources 5.2 arcsec away are flux-capable; s37 PSF residual is 0.87 and the target pixel cannot distinguish them. Sparse four usable trapezoid centers do not yield a secure eclipse ephemeris.',next='Use high-resolution time-series photometry at the narrow phase and a second reduction across several sectors to separate eclipse, spot/tidal waveform and neighbor.',reason='A phase-locked sharp dip recurs in three representative sectors close to Gaia conjunction, but the dominant waveform and crowded pixel field admit non-eclipse or blended explanations. The cached s37 deficit peaks on the target pixel without resolving the 5.2-arcsec sources. No completed physical EB claim follows.',source='Fable 5/made/sb1-scale/c10-flags.md; diffimg/462088261/diff_s37.json'),
'402782627':dict(verdict='confirmed',limitations='Correlated out-of-eclipse variation broadens event scatter; 30-min s18 centers are less precise. TIC radius 6.24 solar radii predicts a longer central event than measured, compatible with grazing geometry or uncertain radius. Cached TESScut is the same TESS photons as QLP.',next='Obtain independent high-cadence photometry and model the eclipse/stellar variation jointly.',reason='Repeated narrow SAP dips in s18, s58 and s86 yield a stable measured period. Cached s24 TESScut aperture sees a matching 13.6-ppt deficit, centered 2.26 arcsec from target; the flux-capable Gaia alternatives are 38 and 51 arcsec away.',source='Fable 5/made/sb1-scale/c10-flags.md; diffimg/402782627/diff_s24.json')}
rows=[]
for r in q:
    tic=r['tic'];m=json.loads((B/tic/'measurements.json').read_text());a=assess[tic];geo=g[tic];pix=n[tic]['stacks'];ev=[e for e in m['events'] if e.get('timing_usable')]
    sec=sorted({e['sector'] for e in ev});stack=pix[0];close=stack['capable_and_borderline'][:4]
    neighbor='; '.join(f"Gaia {x['source_id']} G={x['G']:.2f}, {x['target_sep_arcsec']:.1f}″ from target, approximate intrinsic loss {100*x['required_fraction_at_adopted_depth']:.1f}%{' (borderline >100%)' if x['borderline'] else ''}, {x['deficit_sep_arcsec']:.1f}″ from deficit" for x in close) or 'none within the cached flux-capability threshold'
    note=f"""# TIC {tic} — {a['verdict']} physical review

**Decision.** {a['reason']} Full bounded individual review completed. Catalogue novelty is separate: the shared seven-group scoped checks found no exact prior EB; see `../../shared-catalogues/AUDIT.md` and coverage matrix. This is a review result, not an accepted addition until root integrates it.

**Raw SAP and timing.** Sixteen selected QLP files across this batch were checked against FITS TICID and SECTOR and SHA-256 (`../download-receipts.json`). This target has {len(m['sources'])} representative QLP sectors, {len(ev)} accepted direct trapezoid centers in sectors {sec}; the adopted timing uses {m['timing_event_count']} events. Measured period {m['period_days']:.9f} ± {m['period_error_days']:.9f} d; reference selected-dip epoch BTJD {m['primary_epoch_btjd']:.6f} ± {m['epoch_error_days']:.6f} d; median realized central QLP model depth {m['depth_ppt']:.2f} ppt. Epoch kind: {m['epoch_kind']}. {m['error_meaning']} The model depth is `d*min(1,w/(2*k))`, distinct from extrapolated amplitude `d`. Predicted Gaia conjunctions were not used as measured times. Inspect `raw-events.png`, `phase-review.png`, `raw-windows.csv`, and `measurements.json`.

**Alias and Gaia geometry.** Gaia SB1 P={geo['period_days']:.8f} ± {geo['period_error_days']:.8f} d, e={geo['eccentricity']:.4f}, omega={geo['omega_deg']:.2f}°. Closest observed-epoch conjunction kind {geo['closest']['kind']} is offset {geo['closest']['offset_phase']:+.4f} phase ({geo['closest']['offset_days']:+.3f} d), with {geo['closest']['gaia_covariance_linear_error_days']:.3f} d linear Gaia covariance uncertainty. Both conjunction branches and the full fitted photometric epoch-period covariance projection toward Gaia2016 are in `../gaia-geometry.json`. The Gaia mass function is {geo['mass_function_solar']:.4f} solar masses; TIC radius {geo['tic_radius_solar']:.2f} solar radii, approximate minimum companion {geo['minimum_m2_solar']:.2f} solar masses. These approximate physical scalings assume the TIC mass/radius and edge-on conjunction; they are not a fitted light-curve geometry.

**Pixels and alternative reduction.** Cached TESScut difference image s{stack['sector']} stacks {stack['n_events']} event(s); deficit is {stack['deficit_target_arcsec']:.2f}″ from target, peak pixel {stack['peak_pixel']} versus target pixel {stack['target_pixel']}, 3-pixel aperture loss {stack['ap3_fractional_depth']*1000:.2f} ppt. This is a custom aperture extraction of the same TESS photons, useful as a reduction/attribution cross-check rather than a separate observation. At the adopted depth, the closest flux-capable or borderline Gaia alternatives are: {neighbor}. `../neighbor-inspection.json` records every capable and borderline source in each cached stack and the approximate threshold assumptions. Source-specific claims need this geometry, not peak-pixel coincidence alone.

**Limitations and next check.** {a['limitations']} Next: {a['next']}

**Provenance.** Queue position {r['queue_index']} was frozen independently of outcome. Historical screening source: {a['source']}; frozen `../../source-snapshots/search.jsonl`, `../../source-snapshots/c10-sapdepth.json`, selected metadata `../../targets-selected.json`. Screening ATTR was not the physical verdict.
"""
    (B/tic/'REPORT.md').write_text(note,encoding='utf-8')
    rows.append(dict(tic=tic,physical_verdict=a['verdict'],full_review_completion='complete',period_days=repr(m['period_days']),period_error_days=repr(m['period_error_days']),primary_epoch_btjd=repr(m['primary_epoch_btjd']),depth_ppt=repr(m['depth_ppt']),limitations=a['limitations'],next_check=a['next'],source_report=a['source'],report=f'{tic}/REPORT.md'))
with (B/'RESULTS.csv').open('w',newline='',encoding='utf-8') as f:
    w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
